import sqlite3
c=sqlite3.connect('canon.db')
V='voorlopig';S='vastgesteld'
C=[
# Fundament - land
('Land','Overzicht: het Vijfstromenrijk Velmara',"Een continent rond de binnenzee Ysmer. Noord: ijs en bergen; midden: vruchtbare rivierdelta's; zuid: woestijn en zout; oost: jungle; west: kliffen en eilanden. Kaart in tekst: [Noord] Hoogvrouwe-gebergte — [Midden-noord] Ambergaard — [Midden] Ysmer-delta met hoofdstad Saelith — [West] Zoutkust en Nevel-eilanden — [Oost] Groenmuil-jungle — [Zuid] Rosse Woestijn — [buiten de grens] Het Mannenrijk Kharvos (noordoost) en de Stille Zusterschappen (zuidwest).",V,'Gevarieerde regio’s geven elke etappe van de queeste eigen regels en eigen soort erotische spanning.','Queeste; Regio’s'),
('Regio','Saelith en de Ysmer-delta (centrum)',"Gematigd, warm, overstromingen in de lente. Hoofdstad Saelith: tempelstad op zeven eilanden, zetel van de Orde van de Ontvangst. Steden: Saelith, Orvane, Lisk. Cultuur: hoogste vroomheid, strengste registers, prachtige tempelnachten. Gevaren: politieke moord, overstromingen, tempelwacht. Erotisch: de Grote Wachtrij voor gaven-mannen, publieke Ontvangstriten op de tempeltrappen, de veilingen van de Zaadbeurs, hofintriges waarin elke gunst in bed wordt beslecht.",V,'Machtscentrum; hier zijn de regels het scherpst en het verlangen het meest geregisseerd.','Orde; Huizen; Economie'),
('Regio','Ambergaard (graanland)',"Glooiend, vruchtbaar, droge zomers, oogstfeesten. Steden: Hallowyn, Merk. Cultuur: boerinnencollectieven die samen één gewone man ‘houden’ in een stalhuis; nuchter en direct. Gevaren: misoogst, rondtrekkende zaadrovers. Erotisch: het Oogstbed (een week waarin het stalhuis open is voor alle vrouwen van het dorp, volgens loting), het melken van gewone mannen als boerenambacht, schuurscènes, jaloezie tussen buren.",V,'Voedselschuur van het rijk; toont de ‘melkkoe’-kant van de wereld, aards en direct.','Economie; Gewone mannen'),
('Regio','Hoogvrouwe-gebergte (noord)',"Koud, lange winters, lawines, sneeuwwolven. Steden: Kaldrun (vesting), Ijsgraf (klooster). Cultuur: krijgsvrouwen, mijnbouw (zilver en Sterrensteen), hard en zwijgzaam. Erotisch: winters warmte delen onder bonten, krijgsvrouwen die voor een veldslag het zaad van een gaven-man ontvangen, een berghut tijdens een sneeuwstorm, de duel-om-de-man-traditie.",V,'Leverancier van soldaten en Sterrensteen; kracht en kou geven lijfelijke, rauwe scènes.','Leger; Magie'),
('Regio','Zoutkust en de Nevel-eilanden (west)',"Zilt, mistig, stormen. Steden: Brakhaven (havenstad, zwarte markt), Isla Mirre (piratenhof). Cultuur: zeevaarders, smokkelaarsters, lossere moraal, vrije mannen die zich verhuren. Gevaren: piraterij, ontvoering, zeemonsters. Erotisch: bordelen waar mannen zich verkopen, smokkel van zaad in gekoelde flacons, scheepsruimen, verleiding als betaalmiddel, de vrijheid van een man die ‘los’ loopt.",V,'Ontsnappingsplek en zwarte markt; laat zien wat er buiten de controle van de orde gebeurt.','Zwarte markt; Gewone mannen'),
('Regio','Groenmuil-jungle (oost)',"Heet, vochtig, giftige planten, rivierslangen. Steden: Tuaro (boomstad), ruines van Ves-Anath. Cultuur: oude volkeren die de orde wantrouwen; hier groeit Maankruid (anticonceptie) en Vuurbloesem (lustopwekker). Erotisch: naakte rituelen bij watervallen, plantdrugs die verlangen versterken, de ‘Zwijgende Rit’ met gemaskerde partners, oude geheimen in tempelruines.",V,'Bron van kruiden en het oude geheim; zintuiglijk en gevaarlijk.','Gezondheid; Geheim; Oorsprong'),
('Regio','Rosse Woestijn (zuid)',"Heet overdag, ijskoud ’s nachts, zandstormen, schorpioenen. Steden: Qesh (oase-stad), karavanserai’s. Cultuur: nomadische matriarchen, gaven-man Khaled-Ir als ‘Zonvorst’ in een harem-paleis waar hij heerst, niet de orde. Erotisch: de harem waar vrouwen dingen naar zijn gunst, tentnachten, karavaanhandel in mannen, het Zonnefeest.",V,'Laat zien dat een gaven-man ook kan heersen; tegenhanger van de orde.','Macht; Gaven-mannen'),
('Regio','Kharvos, het Mannenrijk (buitenland, noordoost)',"Een buurvolk waar 1 op 3 een jongen is (ze weten waarom niet, of houden het geheim). Mannen heersen er, vrouwen zijn bezit. Vijandig: Kharvos rooft vrouwen én valt Velmara binnen om gaven-mannen te stelen. Erotisch en donker: gevangenschap, omgekeerde machtsverhoudingen, een vrouw uit Velmara die voor het eerst veel mannen ziet.",V,'Dreiging van buiten en spiegel van Velmara; bron van het geheim.','Buitenwereld; Geheim; Leger'),
('Regio','De Stille Zusterschappen (buitenland, zuidwest)',"Eilanden van vrouwen die mannen afzweren en zich voortplanten via gekocht en bewaard zaad of via oude magie. Handelspartner voor Maankruid en koelmagie, maar ketters in de ogen van de orde. Erotisch: liefde tussen vrouwen als norm, verleiding van een zuster om haar ‘om te praten’, spionnen.",V,'Alternatief voor het systeem; ketterij en handel.','Buitenwereld; Religie'),
# economie
('Economie','Geld',"Munten: de zilveren ‘Druppel’ (dagloon van een arbeidster = 1 Druppel), gouden ‘Kroon’ = 50 Druppels. Daarnaast ‘Gunstbrieven’: verhandelbare tegoedbonnen van de orde voor een plaats in de wachtrij van een gaven-man; dit is de hardste valuta.",V,'Toegang tot zaad is de echte rijkdom; gunstbrieven maken dat verhandelbaar.','Orde; Gaven-mannen'),
('Economie','Wat wordt verhandeld',"Graan (Ambergaard), zilver en Sterrensteen (gebergte), zout, vis en smokkel (west), kruiden (oost), glas, specerijen en paarden (zuid). Daarnaast: gewone mannen (koop, huur, dekgeld), zaad in koelflacons, gunstbrieven, register-afschriften, slavinnen uit Kharvos-razzia’s (verboden, maar het gebeurt).",V,'Elke regio heeft iets wat de andere nodig heeft, dus reizen en handel zijn logisch.','Regio’s; Zwarte markt'),
('Economie','Prijzen van mannen en zaad',"Huur gewone man per nacht: 3-10 Druppels. Koop gewone man: 20-80 Kronen (jong, gezond, vruchtbaar: duurder). Flacon gewoon zaad: 1 Druppel. Eén Ontvangst van een gaven-man: officieel een gunstbrief (wachttijd 1-5 jaar), op de zwarte markt 30-500 Kronen. Koop van een gaven-man: onmogelijk en ondenkbaar; ontvoering is een halsmisdaad.",V,'Concreet prijsverschil laat de klasseverschillen en verleiding voor smokkel zien.','Gewone mannen; Gaven-mannen; Zwarte markt'),
('Economie','Wie werkt',"Vrouwen doen alles: landbouw, mijnbouw, handel, oorlog, bestuur. Gewone mannen werken niet buiten hun stalhuis; hun ‘werk’ is dekken en gemolken worden, 2-4 keer per dag. Gaven-mannen werken niet; ze heersen, vechten of kiezen.",V,'Volgt uit de verhouding; mannen zijn te kostbaar voor gevaarlijk werk.','Demografie'),
# oorsprong
('Oorsprong','Officiële versie (wat het volk gelooft)',"De godin Ysa zond de mannen eens als zondvloed over de wereld; zij waren wreed. Ze nam de meesten weg en liet er één op de honderd over, als gave. Daarom is elke man heilig en is overgave aan hem een dankgebed. De gaven-mannen zijn haar uitverkorenen.",V,'Rechtvaardigt het systeem en geeft de orde haar gezag.','Religie; Orde'),
('Oorsprong','Herkomst van de gave',"De gave is erfelijk via de vader maar slaat over: ongeveer 1 op de 20 zonen van een gaven-man krijgt hem, bij zonen van gewone mannen 1 op 2000. Hij ontwaakt rond het 18e-20e jaar. Daarom wil elk huis het zaad van een gaven-man: kans op een gaven-zoon.",V,'Verklaart de waarde van gaven-zaad en de jacht op jongens van goede lijn.','Magie; Huizen'),
('Oorsprong','HET GEHEIM: de Zegel van Ves-Anath',"Er is geen vloek van de goden. Achthonderd jaar geleden legden de eerste priesteressen in Ves-Anath een bloedzegel over het hele land: een betovering die mannelijke vruchten in de baarmoeder laat vergaan, tot 1 op 100 overblijft. Doel: mannen, die toen in oorlog alles verwoestten, nooit meer de meerderheid laten worden, en de priesteressen de macht te geven. De zegel wordt gevoed door het zaad dat in de tempels wordt ontvangen; elke Ontvangst in een tempel draagt een deel van de kracht af aan de zegel. Daarom eist de orde dat de grote riten in tempels gebeuren. Kharvos ligt buiten de zegel; daarom zijn daar veel mannen.",V,'Geeft de queeste een onthulling die alles omkeert en verklaart demografie, religie en buitenland.','Demografie; Orde; Kharvos; Queeste'),
# geschiedenis
('Geschiedenis','Tijdlijn',"Jaar 0 (‘Jaar van de Zegel’): de zegel wordt gelegd in Ves-Anath na de Mannenoorlogen. 12: eerste afstammingsregisters. 90: oprichting Orde van de Ontvangst in Saelith. 210: eerste gaven-mannen erkend als ‘Uitverkorenen’. 340: de Grote Pest doodt een derde van de mannen; rotatiewet ingevoerd. 455: Huis Varenne sticht de Zaadbeurs. 512: Khaled-Ir’s voorvader sticht het Zonvorstendom in Qesh. 603: Ves-Anath wordt verlaten en door de orde verzwegen. 720: eerste grote Kharvos-inval. 788: de Bloednacht van Lisk, een duistere gaven-man doodt een raad van priesteressen. 801 (heden): de zegel begint te verzwakken; in sommige streken worden meer jongens geboren.",V,'Continuïteit en een klok: de zegel verzwakt nu.','Geheim; Queeste; Huizen'),
# macht
('Macht','De Orde van de Ontvangst',"Priesteressenorde met als hoofd de Hoge Moeder Ithrael (62). Rangen: novice, Ontvangster, Hoedster (beheert mannen), Registratrix, Moeder. Machtsbasis: de registers (wie verwant is, wie mag), de gunstbrieven, de tempelwacht en het geheim van de zegel (alleen de Moeders kennen het).",V,'Toegang en kennis zijn hun dwangmiddelen; religie is hun gereedschap.','Religie; Afstamming; Geheim'),
('Macht','Huis Varenne',"Wapen: zilveren druppel op zwart. Leider: Vrouwe Selvine Varenne. Bezit de Zaadbeurs en de grootste stallen met gewone mannen. Doel: het zaad-monopolie losmaken van de orde en zelf gaven-mannen fokken.",V,'Economische macht tegenover de religieuze.','Economie; Orde'),
('Macht','Huis Kaldra',"Wapen: rode wolf op sneeuw. Leider: Veldvrouwe Brannoch Kaldra. Bergadel, levert het leger en de krijgsvrouwen. Doel: vaste toegang tot gaven-zaad voor haar troepen en oorlog tegen Kharvos.",V,'Militaire macht; heeft zaad-kracht nodig voor oorlog.','Leger; Magie'),
('Macht','Huis Mirre',"Wapen: zwarte schelp op zeegroen. Leider: Kapitein-Vrouwe Ondessa Mirre. Havens, smokkel, zwarte markt. Doel: vrije handel in mannen en zaad, de orde ondermijnen.",V,'Tegenmacht aan de randen; bondgenoot of vijand van de queeste.','Zwarte markt'),
('Macht','Het Zonvorstendom van Qesh',"Wapen: gouden zon met zeven stralen. Leider: Khaled-Ir, een gaven-man die zelf regeert. Doel: onafhankelijkheid van de orde, eigen harem-dynastie.",V,'Bewijs dat een gaven-man kan heersen.','Gaven-mannen'),
('Macht','Evenwicht',"De orde heeft de registers en het geloof, Varenne het geld, Kaldra de zwaarden, Mirre de zee, Qesh een eigen gaven-man. Niemand kan zonder de anderen: Kaldra heeft gaven-zaad nodig van de orde, de orde heeft geld van Varenne, Varenne heeft havens van Mirre. Gaven-mannen zijn de joker: elk huis probeert er een aan zich te binden via de beste vrouwen.",V,'Zorgt voor intriges in plaats van één heerser.','Huizen; Orde'),
('Macht','Leger',"Velmara heeft een groot leger van vrouwen (krijgsvrouwen uit Kaldrun). Voor een slag ontvangen de officieren en de elite het zaad van een gaven-man (‘Strijdontvangst’), wat hen 12 uur lang bovenmenselijk maakt. Gaven-mannen zelf vechten zelden; ze zijn te kostbaar.",V,'Lost op dat vrouwen het leger zijn; zaad is de troef tegen Kharvos.','Magie; Kharvos'),
('Wetten','Wetten en straffen',"Verboden: verwantschapsseks (verbanning of dood), ontvoering van een gaven-man (dood), zaad buiten registratie verhandelen (boete, brandmerk), een man doden (dood), een gaven-man weigeren zonder geldige reden (zie weigering). Rechtspraak: in elke stad een tribunaal van drie Moeders; gaven-mannen staan buiten het gewone recht en worden alleen door de Hoge Moeder berecht.",V,'Duidelijke grenzen geven verbodenheid en inzet.','Orde; Afstamming'),
('Wetten','Wie weigert',"Een vrouw mag een gewone man en elke rite weigeren; dat kost rang (ze daalt in aanzien, krijgt geen gunstbrieven). Een vrouw die een gaven-man die haar kiest weigert, ‘verwerpt de gave’: openbare schande, verlies van gunst voor haar hele huis. Daardoor is weigeren mogelijk maar duur, wat sociale druk en verleiding oplevert. Mannen die weigeren: gewone mannen worden ‘gekalmeerd’ met Vuurbloesem; gaven-mannen kunnen niet gedwongen worden.",V,'Toestemming blijft het formele principe, maar met een sociale prijs; dat geeft spanning zonder de wereld onleefbaar te maken.','Religie; Toestemming'),
# cultuur
('Cultuur','Gezin en wonen',"Geen huwelijk met mannen. Vrouwen leven in ‘moederhuizen’: een groep zussen, vriendinnen en geliefden die samen kinderen opvoeden. Liefde tussen vrouwen is gewoon en vaak de basis van het gezin. Kinderen horen bij het huis van de moeder.",V,'Logisch bij de verhouding; geeft veel relaties en jaloezie.','Demografie'),
('Cultuur','Wat jongens meemaken',"Jongens worden bij de geboorte geregistreerd en op hun zesde naar een ‘Jongenshof’ van de orde gebracht, waar ze beschermd worden opgevoed met les, sport en zorg. Op hun 18e volgt de Wijding: de test op de gave. Wie hem niet heeft, wordt aan een huis toegewezen of verkocht; wie hem heeft, wordt Uitverkorene. Geen seksuele rol voor iemand onder de 18.",V,'Verklaart hoe gaven-mannen en gewone mannen hun pad krijgen; houdt de grens van 18+ hard.','Gaven-mannen; Gewone mannen'),
('Riten','De Inwijding (18+)',"Bij haar 18e jaar wordt een vrouw ingewijd tijdens de Lentenacht: ze kiest uit drie gewone mannen of trekt een lot voor de wachtrij van een gaven-man. Daarna mag ze aan alle riten meedoen.",V,'Duidelijke drempel naar volwassenheid en een vaste scène.','Religie'),
('Riten','De Ontvangst',"De heilige vorm van seks met een gaven-man in de tempel: de vrouw wordt gezalfd, voorbereid door Ontvangsters en ontvangt zijn zaad op het altaarbed, soms in aanwezigheid van getuigen. Zaad kan in de schoot, de mond of op de huid worden ontvangen; voor kracht werkt de schoot het sterkst (100%), de mond 70%, de huid 20%.",V,'Koppelt rite, erotiek en magie met concrete regels.','Magie; Orde'),
('Riten','Feesten',"Lentenacht (inwijding), Oogstbed (Ambergaard), Zonnefeest (Qesh), de Nacht der Duizend Lampen (in Saelith: alle tempels open, elke vrouw mag een man kiezen), de Strijdontvangst voor een oorlog, de Zwijgende Rit (jungle, gemaskerd).",V,'Vaste momenten voor grote, geladen scènes.','Regio’s'),
('Riten','Wachtrijen en veilingen',"De Grote Wachtrij in Saelith: vrouwen wachten met gunstbrieven, soms jaren; wie een gaven-man verleidt buiten de rij, slaat hem over (schandaal en jaloezie). De Zaadbeurs veilt maandelijks huur en koop van gewone mannen en een paar ‘open nachten’ met gaven-mannen die daarmee instemmen.",V,'Concurrentie, anticipatie en macht.','Economie; Orde'),
('Cultuur','Kleding',"Vrouwen dragen lichte, open gewaden; de kleur van de sjerp toont rang en of ze ‘ontvankelijk’ (rood), ‘gezegend’ (goud, net zaad ontvangen) of ‘gesloten’ (grijs, zwanger of niet beschikbaar) is. Gewone mannen dragen een halsband met huiswapen. Gaven-mannen dragen wat ze willen.",V,'Signalen maken verleiding en status zichtbaar.','Riten'),
('Cultuur','Taal en namen',"Vrouwen dragen de naam van hun moederhuis (Selvine van Varenne). Gewone mannen krijgen een stalnaam (Bram-van-de-Hallowynstal). Gaven-mannen kiezen zelf een naam met ‘-ir’ of ‘-as’. Woorden: ‘ontvangen’ (seks met zaad), ‘gezegend zijn’ (onder zaad-kracht), ‘droog’ (in ontwenning).",V,'Taal toont macht en het geloof.','Cultuur'),
('Cultuur','Eten, kunst en bijgeloof',"Eten: graan, vis, honing en ‘mannenvoer’ (oesters, eieren, Ambergaardse bonen) voor mannen. Kunst: tempelfresco’s van Ontvangsten, liefdespoëzie tussen vrouwen, beelden van gaven-mannen. Bijgeloof: een vrouw die een jongen baart is gezegend; zaad op de drempel brengt geluk; wie droomt van een gaven-man wordt binnen een jaar gekozen.",V,'Kleur en details voor scènes.','Cultuur'),
('Gezondheid','Zwangerschap, anticonceptie en onvruchtbaarheid',"Elke vrouw krijgt gemiddeld 4 kinderen. Maankruid (jungle) voorkomt bevruchting maar laat de zaad-kracht intact; daarom gebruiken krijgsvrouwen het. Onvruchtbare vrouwen worden Hoedsters of soldaten en ‘mogen’ zaad zonder voortplantingsplicht. Zwangere vrouwen krijgen 4x minder kracht van zaad.",V,'Scheidt lust en kracht van voortplanting, wat meer situaties oplevert.','Magie; Demografie'),
# magie
('Magie','Wat een gaven-man kan',"Elke gaven-man heeft één element of kracht: vuur, storm, aarde, bloed, stem (overtuigen en bevelen) of geest (gevoel lezen en sturen). Met zijn gave kan hij een groep soldaten verslaan of een huis beschermen. Prijs: elk gebruik kost hem kracht en maakt hem dorstig naar aanraking; na grote magie moet hij binnen een dag ‘ontladen’ (seks/zaad geven), anders krijgt hij koorts. Hij kan niet: doden met zijn gedachten, zaad van anderen laten werken, de zegel breken.",V,'Prijs maakt magie en seks onlosmakelijk; dat geeft dwang en verlangen aan beide kanten.','Gaven-mannen'),
('Magie','Kracht en duur van zaad',"Gewone man: +20% kracht en snelheid, 1-3 uur. Gaven-man: tot 5x menselijke kracht, snelheid en genezing, 8-12 uur, en een vleug van zijn element (vuur, storm …). Meerdere Ontvangsten tellen niet op boven 5x maar verlengen de duur tot max 24 uur. Daarna volgt de ‘Leegte’: 1-2 dagen uitputting en verlangen.",S,'Vastgelegde getallen maken de economie en oorlog berekenbaar (volgt uit open vraag ronde 2).','Economie; Leger'),
('Magie','Verslaving en tegenmiddelen',"Wie vaker dan 3 keer per maand gaven-zaad ontvangt, raakt ‘gebonden’: zonder zaad volgen trillingen, koorts en hevig verlangen, vooral naar die ene man. Tegenmiddel: Grijswortel (jungle) breekt de binding in 9 dagen, maar is bitter en pijnlijk. Gebonden vrouwen zijn het machtsmiddel van duistere gaven-mannen.",V,'Afhankelijkheid geeft donkere inzet en macht.','Gaven-mannen; Verhaal'),
# verhaal
('Personage','Liora van Hallowyn (hoofdpersoon)',"25 jaar, boerendochter uit Ambergaard, opgegroeid in een arm moederhuis. Kwetsbaar: ze heeft een verkeerde bloedlijn (haar register is vervalst), is onervaren met gaven-mannen en zonder gunstbrief. Ze ontdekt dat haar halfbroer Teo een verborgen gave heeft. Doel: Teo beschermen en de waarheid achter de zegel vinden. Ze kan als enige zaad-kracht verdragen zonder Leegte (een gevolg van de verzwakte zegel).",V,'Een vrouw met iets om te verliezen en iets wat anderen willen.','Queeste; Geheim'),
('Personage','Aeron-as (lieve gaven-man)',"35, stormgave, ooit Uitverkorene in Saelith, nu op de vlucht omdat hij weigerde een gebonden vrouw te dwingen. Warm, schuldbewust, beschermend; zijn zaad geeft lichtere binding. Wordt Liora’s geliefde en bondgenoot.",V,'Romantische en zorgzame pool.','Gaven-mannen'),
('Personage','Morvane-ir (duistere gaven-man)',"40, bloedgave, de Bloedvorst van Lisk. Bindt vrouwen aan zich met zijn zaad en heeft een harem van gebonden krijgsvrouwen. Wil de zegel breken om met Kharvos het rijk over te nemen. Verleidelijk, wreed en charmant.",V,'Duistere pool; verleiding met gevaar.','Gaven-mannen; Kharvos'),
('Personage','Khaled-Ir (dubbelzinnige gaven-man)',"45, vuurgave, Zonvorst van Qesh. Heerst over een harem en zijn rijk. Hij helpt Liora als het hem macht geeft, maar verlangt een prijs: een seizoen in zijn harem.",V,'Dubbelzinnige pool: bondgenoot met een prijs.','Qesh'),
('Personage','Bondgenoten',"Sef van Brakhaven (smokkelaarster en Liora’s minnares); Hoedster Imra (priesteres die twijfelt en het geheim half kent); Ondessa Mirre (kapitein).",V,'Steun met eigen motief.','Huis Mirre; Orde'),
('Personage','Tegenstanders',"Hoge Moeder Ithrael (bewaakt het geheim); Selvine Varenne (wil Teo als fokman); Morvane-ir; de Kharvos-krijgsheer Drask.",V,'Meerdere bedreigingen met verschillende motieven.','Orde; Huizen'),
('Personage','Gewone mannen',"Teo (18, Liora’s halfbroer, net gewijd; heeft een verborgen gave; geen seksuele rol vóór zijn wijding en niet met Liora, verwantschap). Bram (30, melkman uit de Hallowynstal, gelaten maar slim; hij kent geheimen uit het bed en wil vrij zijn).",V,'Toont de ‘melkkoe’-kant en een man die zijn lot wil veranderen.','Gewone mannen; Verwantschap'),
('Verhaal','Doel, reden en gevaar van de queeste',"Doel: Ves-Anath bereiken en de zegel vinden. Reden: de zegel verzwakt; de orde wil hem vernieuwen met een groot offer van zaad (en Teo’s gave), Morvane-ir wil hem breken. Gevaar: de orde, de huizen en Kharvos jagen op Teo en op Liora. Keuze aan het eind: de zegel breken (vrijheid en chaos), herstellen (orde), of veranderen.",V,'Geeft de reis een klok, een vijand en een morele keuze.','Geheim; Personages'),
('Verhaal','Etappes van de queeste',"1. Hallowyn: Teo wordt gewijd en verkocht; het Oogstbed is de dekmantel voor de vlucht. 2. Merk: zaadrovers; Liora ontmoet Aeron-as. 3. Saelith: de Nacht der Duizend Lampen; ze moet een gaven-man verleiden om binnen te komen. 4. Brakhaven: zwarte markt, bordeel, Sef. 5. Nevel-eilanden: piratenhof van Mirre; verleiding als betaling. 6. Qesh: Khaled-Ir’s harem, de prijs. 7. Rosse Woestijn: tentnachten met Aeron, vlucht voor Morvane-ir. 8. Kaldrun: Strijdontvangst voor een veldslag tegen Kharvos. 9. Groenmuil: de Zwijgende Rit en Grijswortel tegen binding. 10. Ves-Anath: de zegel, de laatste keuze.",V,'Elke etappe heeft een eigen geladen scène en een eigen regio.','Regio’s; Riten'),
('Geheimen','Wie weet wat',"Het volk: gelooft de officiële versie. De orde: de Moeders kennen de zegel en weten dat hij met tempelzaad wordt gevoed. Niemand: dat de zegel ook de gave veroorzaakt (de gave is de kracht van de vernietigde zonen die in de overlevende zonen terechtkomt). Als de zegel breekt, verdwijnen ook de gaven.",V,'Laag met dubbele bodem: een zegel breken kost de gaven-mannen hun macht.','Geheim; Magie'),
]
