# export
L=['# Canon Velmara\n']
cats=[r[0] for r in c.execute('select distinct categorie from canon order by min(id) over (partition by categorie)')]
seen=[]
for (k,) in c.execute('select categorie from canon order by id'):
  if k not in seen: seen.append(k)
for k in seen:
  L.append(f'\n## {k}\n')
  for o,f,s,r,h,ro in c.execute('select onderwerp,feit,status,reden,hangt_samen_met,ronde from canon where categorie=? order by id',(k,)):
    L.append(f'- **{o}** ({s}, ronde {ro}): {f}\n  - Reden: {r} | Hangt samen met: {h}')
L.append('\n## Wrijvingen\n')
for i,t,d,b,ty,s in c.execute('select * from wrijving'): L.append(f'{i}. **{t}** [{ty}, {s}] ({d}): {b}')
L.append('\n## Open vragen\n')
for i,v,w,s,a in c.execute('select * from open_vraag'): L.append(f'{i}. {v} [{s}] — {w}'+(f' — {a}' if a else ''))
open('canon.md','w').write('\n'.join(L)+'\n')
for t in ['canon','wrijving','open_vraag','logboek']: print(t,c.execute(f'select count(*) from {t}').fetchone())
